pub async fn bulk_ops(
    State(state): State<AppState>,
    Path(index): Path<String>,
    axum::extract::Query(qp): axum::extract::Query<std::collections::HashMap<String, String>>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    let started = Instant::now();
    let opts = bulk_opts_from_query(&qp);
    process_bulk_body(&state, Some(&index), &body, started, opts).await
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_bulk — global bulk
// ─────────────────────────────────────────────────────────────────────────────

pub async fn global_bulk(
    State(state): State<AppState>,
    axum::extract::Query(qp): axum::extract::Query<std::collections::HashMap<String, String>>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    let started = Instant::now();
    let opts = bulk_opts_from_query(&qp);
    process_bulk_body(&state, None, &body, started, opts).await
}

fn bulk_opts_from_query(
    qp: &std::collections::HashMap<String, String>,
) -> xerj_engine::bulk::BulkOpts {
    // `?_source=true` / `?_source=field` / `?_source_includes=f1,f2` /
    // `?_source_excludes=f3` — translate the ES URL-shape to the
    // search body `_source` filter shape the engine consumes.
    let default_source_req: Option<Value> = {
        let src_param = qp.get("_source");
        let inc = qp.get("_source_includes");
        let exc = qp.get("_source_excludes");
        if inc.is_some() || exc.is_some() {
            let mut obj = serde_json::Map::new();
            if let Some(v) = inc {
                let arr: Vec<Value> = v
                    .split(',')
                    .map(|s| Value::String(s.trim().to_string()))
                    .collect();
                obj.insert("includes".to_string(), Value::Array(arr));
            }
            if let Some(v) = exc {
                let arr: Vec<Value> = v
                    .split(',')
                    .map(|s| Value::String(s.trim().to_string()))
                    .collect();
                obj.insert("excludes".to_string(), Value::Array(arr));
            }
            Some(Value::Object(obj))
        } else if let Some(v) = src_param {
            match v.as_str() {
                "true" => Some(Value::Bool(true)),
                "false" => Some(Value::Bool(false)),
                other => {
                    let arr: Vec<Value> = other
                        .split(',')
                        .map(|s| Value::String(s.trim().to_string()))
                        .collect();
                    Some(Value::Array(arr))
                }
            }
        } else {
            None
        }
    };
    xerj_engine::bulk::BulkOpts {
        require_alias: qp.get("require_alias").and_then(|v| match v.as_str() {
            "true" => Some(true),
            "false" => Some(false),
            _ => None,
        }),
        default_source_req,
        // `?pipeline=` — the request-level default for every `index`/`create`
        // action that names no pipeline of its own. Read but discarded before
        // (issue #204): the bulk item was written untransformed under a `201`.
        default_pipeline: qp.get("pipeline").cloned(),
    }
}

/// Render the indices a bulk touched for its audit note, bounded.
///
/// An audit entry is evidence, not a report: it says which indices the request
/// wrote to, and says plainly when there were more than it lists rather than
/// silently truncating. The bound exists because the entry shares a fixed-size
/// ring with every other event on the node.
fn render_index_list(names: &std::collections::BTreeSet<String>) -> String {
    const SHOWN: usize = 8;
    let listed = names
        .iter()
        .take(SHOWN)
        .map(String::as_str)
        .collect::<Vec<_>>()
        .join(",");
    if names.len() > SHOWN {
        format!("{listed},+{} more", names.len() - SHOWN)
    } else {
        listed
    }
}

async fn process_bulk_body(
    state: &AppState,
    default_index: Option<&str>,
    body: &bytes::Bytes,
    _started: Instant,
    opts: xerj_engine::bulk::BulkOpts,
) -> axum::response::Response {
    // The request body remains owned by this handler through parsing,
    // grouping, and publication. The opt-in guard is a single branch and
    // performs no atomic work when tracing is disabled.
    let _http_body_memory = xerj_engine::ingest_memory::Retained::new(
        xerj_engine::ingest_memory::Category::HttpBody,
        body.len(),
    );
    let text = match std::str::from_utf8(body) {
        Ok(t) => t,
        Err(_) => {
            let e = xerj_common::XerjError::serialization("bulk body is not valid UTF-8");
            return ApiError::new(e).into_response();
        }
    };

    // ES bulk NDJSON alternates action-lines and source-lines. We rewrite
    // each source line through apply_ignore_malformed so the downstream
    // bulk pipeline sees a doc with _ignored already populated and any
    // malformed values stripped, matching the path taken by the single-
    // doc PUT _doc/{id} / POST _doc routes.
    // TSDB last-wins `_id` rewrite: for `time_series`-mode indices, inject a
    // deterministic `_id` derived from the COMPLETE `_tsid` (all dimension
    // fields — mapping-declared `time_series_dimension:true` AND every
    // `routing_path` entry, nested paths resolved) plus the normalized
    // `@timestamp`. Two docs collapse (later overwrites earlier) ONLY when all
    // dimensions and the instant are identical, matching ES. Returns `None`
    // when no action targets a TSDB index, so normal bulk bodies are unchanged.
    let ts_rewritten = rewrite_bulk_time_series_ids(state, default_index, text);
    let _ts_rewritten_memory = ts_rewritten.as_ref().map(|replacement| {
        xerj_engine::ingest_memory::Retained::new(
            xerj_engine::ingest_memory::Category::HttpRewriteBuffer,
            replacement.capacity(),
        )
    });
    let base_text: &str = ts_rewritten.as_deref().unwrap_or(text);

    let rewritten_body;
    let mut rewritten_capacity = None;
    // P2.2 — the ignore_malformed rewrite parses + re-serialises EVERY
    // source line serially (client-blocking).  `apply_ignore_malformed`
    // can only modify a doc when some field in the target mapping carries
    // `ignore_malformed: true` or `ignore_above`; when no known mapping
    // declares either directive the whole pass is a guaranteed no-op, so
    // skip it instead of round-tripping the body through serde.
    let text_ref: &str = if state.engine.index_mappings.is_empty()
        || !state
            .engine
            .index_mappings
            .iter()
            .any(|e| mapping_has_ignore_directives(e.value()))
    {
        base_text
    } else {
        rewritten_body = rewrite_bulk_ignore_malformed(state, default_index, base_text);

    rewritten_body = rewrite_bulk_ignore_malformed(state, default_index, base_text);
    rewritten_capacity = Some(rewritten_body.capacity());
    &rewritten_body
};
let _ignore_rewritten_memory = rewritten_capacity.map(|capacity| {
    xerj_engine::ingest_memory::Retained::new(
        xerj_engine::ingest_memory::Category::HttpRewriteBuffer,
        capacity,
    )
});

let result =
    xerj_engine::bulk::process_bulk_with_opts(&state.engine, default_index, text_ref, opts)
        .await;
let took_ms = result.took_ms;
let errors = result.errors;

// Top-level HTTP status: if ALL items came back 429, return a top-level
// 429 so clients that only look at the HTTP code (e.g. stock Python
// urllib) also back off.  If only some items are 429 we still return 200
// per ES bulk semantics, and the client is expected to read per-item
// statuses.
let all_backpressure = !result.items.is_empty() && result.items.iter().all(|i| i.status == 429);

// RC4 W4 item 2: tally successfully-written docs per index so the
// `docs_indexed` / `docs_indexed_by_index` counters reflect bulk ingest.
// The bulk pipeline is the demo's primary ingest path and previously never
// touched these counters — they read 0 even at millions of docs. Tallied
// locally and flushed with one `inc_by` per index after the loop (keeps the
// global atomic off the per-doc hot path). `item.index` here is the
// concrete resolved index, so the label set stays bounded.
let mut docs_indexed_tally: std::collections::HashMap<String, u64> =
    std::collections::HashMap::new();
// Issue #329: the audit entry for this request reports what it covered.
let mut failed_items = 0u64;
let mut audited_index_names: std::collections::BTreeSet<String> =
    std::collections::BTreeSet::new();
let mut items: Vec<EsBulkItem> = Vec::with_capacity(result.items.len());
for item in result.items {
    if item.error.is_some() || !(200..300).contains(&item.status) {
        failed_items += 1;
    }
    audited_index_names.insert(item.index.clone());
    if item.error.is_none()
        && (200..300).contains(&item.status)
        && matches!(item.action.as_str(), "index" | "create" | "update")
    {
        *docs_indexed_tally.entry(item.index.clone()).or_insert(0) += 1;
    }
    let get = item.get_source.clone().map(|s| {
        serde_json::json!({
            "found": true,
            "_source": s,
        })
    });
    // Real per-item `_seq_no` / `_version` — same resolvers `_mget` and
    // GET `_doc` use (were hardcoded `_version: 1` / a wall-clock
    // timestamp masquerading as `_seq_no`).
    let (version, seq_no) = state
        .engine
        .get_index(&item.index)
        .ok()
        .map(|idx| {
            (
                idx.lookup_version(&item.id).unwrap_or(1),
                idx.lookup_seq_no(&item.id).unwrap_or(0),
            )
        })
        .unwrap_or((1, 0));
    let item_result = EsBulkItemResult {
        index: item.index,
        id: item.id,
        version,
        // A successful action with no explicit result is a `delete`
        // (the only one that does not set one). A FAILED action has no
        // result at all — see `EsBulkItemResult::result`.
        result: if item.error.is_some() {
            None
        } else {
            Some(item.result.clone().unwrap_or_else(|| "deleted".to_string()))
        },
        shards: crate::responses::EsShards::single_success(),
        seq_no,
        primary_term: 1,
        status: item.status,
        get,
        error: item.error.map(|e| {
            // Map common per-item error phrases to their ES exception
            // type names so clients can match on `error.type`.
            let error_type = if e.starts_with("if _id is specified")
                || e.contains("missing document body")
                || e.contains("unknown action type")
                || e.contains("no write index is defined")
                || e.starts_with("pipeline with id")
            {
                "illegal_argument_exception"
            } else if e.starts_with("version conflict") {
                "version_conflict_engine_exception"
            } else if e.contains("index not found") || e.starts_with("no such index") {
                "index_not_found_exception"
            } else if e.contains("dynamic template")
                || e.contains("failed to parse field")
                // Malformed doc-body JSON on a bulk item: ES 8.13
                // reports `document_parsing_exception` ("[1:1] failed
                // to parse: ..."), not illegal_argument.
                || e.contains("invalid document JSON")
            {
                "document_parsing_exception"
            } else {
                "engine_exception"
            }
            .to_string();
            BulkItemError {
                error_type,
                reason: e,
                status: item.status,
            }
        }),
    };
    let action = EsBulkItem {
        action: match item.action.as_str() {
            "index" => EsBulkItemAction::Index(item_result),
            "create" => EsBulkItemAction::Create(item_result),
            "update" => EsBulkItemAction::Update(item_result),
            "delete" => EsBulkItemAction::Delete(item_result),
            _ => EsBulkItemAction::Index(item_result),
        },
    };
    items.push(action);
}

// RC4 W4 item 2: flush the per-index docs-indexed tally (one atomic inc_by
// per index) now the whole batch is accounted for.
for (idx_name, n) in &docs_indexed_tally {
    state.metrics.record_docs_indexed(idx_name, *n);
}

